import {pathFollowDefaults} from './path-follow-settings.js';
const shadowDefaults={shadowEnabled:false,shadowX:12,shadowY:12,shadowBlur:12,shadowOpacity:.35,shadowColor:'#000000'};import {cubicProgress,limitValue} from './curves.js';
import {lineNoiseDefaults} from '../scene/line-noise.js';
import {clone,walk,animatable} from '../document/model.js';
const autoKeyPolicies=new WeakMap();
export function configureAutoKey(project,enabled,ease='easeInOut'){walk(project.layers,n=>autoKeyPolicies.set(n,{enabled:!!enabled,ease}));}

const bounceOut=t=>{const n=7.5625,d=2.75;if(t<1/d)return n*t*t;if(t<2/d){t-=1.5/d;return n*t*t+.75;}if(t<2.5/d){t-=2.25/d;return n*t*t+.9375;}t-=2.625/d;return n*t*t+.984375;};
export const easing={bounceOut,bounceIn:t=>1-bounceOut(1-t),hold:()=>0,linear:t=>t,easeIn:t=>t*t,easeOut:t=>1-(1-t)**2,easeInOut:t=>t<.5?2*t*t:1-(-2*t+2)**2/2};
function rgb(c){if(/^#[0-9a-f]{3}$/i.test(c))c='#'+[...c.slice(1)].map(x=>x+x).join('');return /^#[0-9a-f]{6}$/i.test(c)?[1,3,5].map(i=>parseInt(c.slice(i,i+2),16)):null;}
export function compatible(a,b){return Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&a.every((n,i)=>!!n.move===!!b[i].move&&!!n.close===!!b[i].close&&['in','out'].every(k=>!!n[k]===!!b[i][k]));}
export function interpolate(a,b,t){if(typeof a==='number'&&typeof b==='number')return a+(b-a)*t;if(typeof a==='string'){const ca=rgb(a),cb=rgb(b);if(ca&&cb)return '#'+ca.map((v,i)=>Math.max(0,Math.min(255,Math.round(v+(cb[i]-v)*t))).toString(16).padStart(2,'0')).join('');}if(a?.points&&b?.points&&a.rows===b.rows&&a.cols===b.cols)return {...clone(a),bounds:Object.fromEntries(['x','y','width','height'].map(k=>[k,interpolate(a.bounds[k],b.bounds[k],t)])),points:a.points.map((p,i)=>({x:interpolate(p.x,b.points[i].x,t),y:interpolate(p.y,b.points[i].y,t),color:interpolate(p.color,b.points[i].color,t)}))};if(compatible(a,b))return a.map((n,i)=>{const o={...n,x:interpolate(n.x,b[i].x,t),y:interpolate(n.y,b[i].y,t)};if(n.bevelRadius!==undefined||b[i].bevelRadius!==undefined)o.bevelRadius=interpolate(n.bevelRadius||0,b[i].bevelRadius||0,t);if(n.bevelStyle!==undefined||b[i].bevelStyle!==undefined)o.bevelStyle=t<1?(n.bevelStyle||'round'):(b[i].bevelStyle||'round');for(const k of ['in','out'])if(n[k])o[k]={x:interpolate(n[k].x,b[i][k].x,t),y:interpolate(n[k].y,b[i][k].y,t)};return o;});return clone(t<1?a:b);}
export function evaluateTrack(track,time,base){if(!track?.length)return base;if(time<=track[0].time)return clone(track[0].value);for(let i=1;i<track.length;i++){const b=track[i],a=track[i-1];if(time<b.time){const t=(time-a.time)/(b.time-a.time);return interpolate(a.value,b.value,a.bezier?cubicProgress(t,a.bezier):(easing[a.easing]||easing.linear)(t));}}return clone(track.at(-1).value);}
export function evaluated(n,time){const result={...shadowDefaults,...lineNoiseDefaults,...pathFollowDefaults,...n};for(const [p,t] of Object.entries(n.tracks||{})){result[p]=evaluateTrack(t,time,result[p]);if(typeof result[p]==='number')result[p]=limitValue(p,result[p]);}for(const cut of n.blockCuts||[])if(time>=cut.start&&time<cut.end)Object.assign(result,clone(cut.values));for(const block of n.blocks||[])if(time>=block.start&&time<block.end)for(const [p,t] of Object.entries(block.tracks||{})){result[p]=evaluateTrack(t,time,result[p]);if(typeof result[p]==='number')result[p]=limitValue(p,result[p]);}return result;}
function propertyBlock(n,prop,time){const active=(n.blocks||[]).filter(b=>b.tracks&&time>=b.start&&time<b.end);return active.findLast(b=>Object.hasOwn(b.tracks,prop))||active.at(-1);}
function maskedCut(n,prop,time){
 const cut=(n.blockCuts||[]).findLast(c=>time>=c.start&&time<c.end&&Object.hasOwn(c.values,prop));
 if(!cut||(n.blocks||[]).some(b=>time>=b.start&&time<b.end&&b.tracks?.[prop]?.length))return null;return cut;
}
function cutEditBlock(n,prop,time,cut){
 // A bounded override leaves every existing held value and global curve intact.
 let end=cut.end;for(const c of n.blockCuts||[])if(Object.hasOwn(c.values,prop))for(const edge of [c.start,c.end])if(edge>time)end=Math.min(end,edge);
 for(const b of n.blocks||[])if(b.tracks?.[prop]?.length)for(const edge of [b.start,b.end])if(edge>time)end=Math.min(end,edge);
 const shared=(n.blocks||[]).findLast(b=>b.tracks&&Math.abs(b.start-time)<.00001&&Math.abs(b.end-end)<.00001);if(shared){shared.tracks[prop]??=[];return shared;}
 if((n.blocks?.length||0)>=1000)throw Error('Too many animation blocks. Remove an unused block before editing this held range.');
 const block={id:globalThis.crypto.randomUUID(),name:'Edited held pose',kind:'animation',start:time,end,props:[prop],tracks:{[prop]:[]}};(n.blocks??=[]).push(block);return block;
}
export function putKey(n,prop,time,value,ease='easeInOut'){const cut=maskedCut(n,prop,time),block=cut?cutEditBlock(n,prop,time,cut):propertyBlock(n,prop,time),tracks=block?.tracks||n.tracks;if(block&&!tracks[prop])tracks[prop]=(n.tracks[prop]||[]).map(k=>({...clone(k),id:globalThis.crypto.randomUUID()}));const track=tracks[prop]||=[];if(block&&!block.props.includes(prop))block.props.push(prop);let key=track.find(k=>Math.abs(k.time-time)<.00001);if(key){key.value=clone(value);}else{key={id:globalThis.crypto.randomUUID(),time,value:clone(value),easing:ease};track.push(key);}track.sort((a,b)=>a.time-b.time);return key;}
export function enableTrack(n,prop,time,ease='easeInOut'){const value=clone(evaluated(n,time)[prop]);if(maskedCut(n,prop,time))return putKey(n,prop,time,value,ease);const tracks=activeTracks(n,time),block=propertyBlock(n,prop,time),first=block?.start||0;if(!tracks[prop]?.length&&time>first)putKey(n,prop,first,evaluated(n,first)[prop]??shadowDefaults[prop],ease);return putKey(n,prop,time,value,ease);}
export function activeTracks(n,time){const tracks={...n.tracks};for(const block of n.blocks||[])if(block.tracks&&time>=block.start&&time<block.end)Object.assign(tracks,block.tracks);return tracks;}
export function allTracks(n){return [n.tracks,...(n.blocks||[]).map(b=>b.tracks).filter(Boolean)];}
export function setProperty(n,prop,value,time){if(maskedCut(n,prop,time)){if(JSON.stringify(evaluated(n,time)[prop])===JSON.stringify(value))return;return putKey(n,prop,time,value,autoKeyPolicies.get(n)?.ease||'easeInOut');}const tracks=activeTracks(n,time),policy=autoKeyPolicies.get(n);if(policy?.enabled&&animatable.includes(prop)&&!tracks[prop]?.length&&!n.tracks[prop]?.length&&JSON.stringify(evaluated(n,time)[prop])!==JSON.stringify(value)){enableTrack(n,prop,time,policy.ease);Object.assign(tracks,activeTracks(n,time));} if(prop==='nodes'&&!tracks.nodes?.length&&allTracks(n).some(tracks=>Object.values(tracks).some(t=>t.length))){const block=n.blocks?.findLast(b=>b.tracks&&time>=b.start&&time<b.end);putKey(n,'nodes',block?.start||0,evaluated(n,block?.start||0).nodes);}if(tracks[prop]?.length||n.tracks[prop]?.length)putKey(n,prop,time,value);else n[prop]=value;}
